import schedule from"node-schedule";const jobOptions={"time-3":{cron:"0 3 * * *",jobs:[]},"time-4":{cron:"0 4 * * *",jobs:[]}};export function addJob(o,n){const t=jobOptions[o].jobs;t&&t.push(n)}export function removeJob(o,n){const t=jobOptions[o].jobs;if(!t)return;const s=t.findIndex(o=>o===n);-1!==s&&t.splice(s,1)}export function start(){Object.keys(jobOptions).forEach(o=>{const n=jobOptions[o].cron,t=jobOptions[o].jobs;schedule.scheduleJob(n,function(){t.forEach(o=>{o()})})})}